SELECT COUNT(*) FROM message
WHERE conversation_id = #{conversationId}
AND to_user_id = #{userId}
AND status = 0

SELECT conversation_id AS conversationId, COUNT(*) AS unreadCount FROM message WHERE to_user_id = #{userId} AND status = 0 AND conversation_id IN
#{conversationId}
GROUP BY conversation_id

